import{_ as e,o as n,c as t,a0 as s}from"./chunks/framework.BpJS36ta.js";const b=JSON.parse('{"title":"Built-in Functions","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/builtins.md","filePath":"syntax/builtins.md"}'),p={name:"syntax/builtins.md"};function i(d,a,r,o,l,c){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="built-in-functions" tabindex="-1">Built-in Functions <a class="header-anchor" href="#built-in-functions" aria-label="Permalink to &quot;Built-in Functions&quot;">​</a></h1><p>Fungsi bawaan yang tersedia tanpa import.</p><h2 id="type-value" tabindex="-1">type(value) <a class="header-anchor" href="#type-value" aria-label="Permalink to &quot;type(value)&quot;">​</a></h2><p>Mengembalikan tipe data sebagai string.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(type(5))        // number</span></span>
<span class="line"><span>print(type(3.14))     // decimal</span></span>
<span class="line"><span>print(type(&quot;hello&quot;))  // string</span></span>
<span class="line"><span>print(type(true))     // boolean</span></span>
<span class="line"><span>print(type(null))     // null</span></span>
<span class="line"><span>print(type([1,2]))    // array</span></span>
<span class="line"><span>print(type({a: 1}))   // object</span></span>
<span class="line"><span>print(type(fn() {}))  // function</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tipe</th><th>Return</th></tr></thead><tbody><tr><td><code>5</code></td><td><code>&quot;number&quot;</code></td></tr><tr><td><code>3.14</code></td><td><code>&quot;decimal&quot;</code></td></tr><tr><td><code>&quot;hello&quot;</code></td><td><code>&quot;string&quot;</code></td></tr><tr><td><code>true</code></td><td><code>&quot;boolean&quot;</code></td></tr><tr><td><code>null</code></td><td><code>&quot;null&quot;</code></td></tr><tr><td><code>[1,2]</code></td><td><code>&quot;array&quot;</code></td></tr><tr><td><code>{a: 1}</code></td><td><code>&quot;object&quot;</code></td></tr><tr><td><code>fn() {}</code></td><td><code>&quot;function&quot;</code></td></tr></tbody></table><h2 id="len-value" tabindex="-1">len(value) <a class="header-anchor" href="#len-value" aria-label="Permalink to &quot;len(value)&quot;">​</a></h2><p>Mengembalikan panjang string, array, atau jumlah key object.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(len(&quot;hello&quot;))     // 5</span></span>
<span class="line"><span>print(len([1, 2, 3]))   // 3</span></span>
<span class="line"><span>print(len({a: 1, b: 2})) // 2</span></span></code></pre></div><h2 id="isnull-value" tabindex="-1">isNull(value) <a class="header-anchor" href="#isnull-value" aria-label="Permalink to &quot;isNull(value)&quot;">​</a></h2><p>Mengembalikan <code>true</code> jika value null.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(isNull(null))    // true</span></span>
<span class="line"><span>print(isNull(0))       // false</span></span>
<span class="line"><span>print(isNull(&quot;&quot;))      // false</span></span></code></pre></div><h2 id="tonumber-value" tabindex="-1">toNumber(value) <a class="header-anchor" href="#tonumber-value" aria-label="Permalink to &quot;toNumber(value)&quot;">​</a></h2><p>Konversi value ke number.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(toNumber(&quot;42&quot;))    // 42</span></span>
<span class="line"><span>print(toNumber(&quot;3.14&quot;))  // 3</span></span>
<span class="line"><span>print(toNumber(true))    // 1</span></span>
<span class="line"><span>print(toNumber(null))    // 0</span></span></code></pre></div><h2 id="tostring-value" tabindex="-1">toString(value) <a class="header-anchor" href="#tostring-value" aria-label="Permalink to &quot;toString(value)&quot;">​</a></h2><p>Konversi value ke string.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(toString(42))     // &quot;42&quot;</span></span>
<span class="line"><span>print(toString(true))   // &quot;true&quot;</span></span>
<span class="line"><span>print(toString(null))   // &quot;null&quot;</span></span></code></pre></div><h2 id="sizeof-typename" tabindex="-1">sizeof(TypeName) <a class="header-anchor" href="#sizeof-typename" aria-label="Permalink to &quot;sizeof(TypeName)&quot;">​</a></h2><p>Ukuran representasi tipe dalam byte. Argumennya <strong>nama tipe</strong>, bukan value — menerima scalar, struct terdaftar, dan bentuk array <code>T[]</code>.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Point { x: number, y: number }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(sizeof(number))   // 4</span></span>
<span class="line"><span>print(sizeof(decimal))  // 8</span></span>
<span class="line"><span>print(sizeof(boolean))  // 1</span></span>
<span class="line"><span>print(sizeof(string))   // 8  (char*)</span></span>
<span class="line"><span>print(sizeof(ptr))      // 8  (void*)</span></span>
<span class="line"><span>print(sizeof(Point))    // 8  (jumlah field scalar)</span></span>
<span class="line"><span>print(sizeof(number[])) // 16 (representasi array: items + length)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tipe</th><th>Ukuran</th></tr></thead><tbody><tr><td><code>number</code></td><td>4</td></tr><tr><td><code>decimal</code></td><td>8</td></tr><tr><td><code>boolean</code></td><td>1</td></tr><tr><td><code>string</code></td><td>8</td></tr><tr><td><code>ptr</code></td><td>8</td></tr><tr><td><code>Struct</code></td><td>jumlah ukuran field (rekursif untuk struct bertingkat)</td></tr><tr><td><code>T[]</code></td><td>representasi array (16)</td></tr></tbody></table><h2 id="new-contract-—-anotasi-sebagai-spesifikasi-alokasi" tabindex="-1">new Contract() — anotasi sebagai spesifikasi alokasi <a class="header-anchor" href="#new-contract-—-anotasi-sebagai-spesifikasi-alokasi" aria-label="Permalink to &quot;new Contract() — anotasi sebagai spesifikasi alokasi&quot;">​</a></h2><p>Tipe disebut <strong>sekali</strong>, di anotasi — tanpa <code>new Object()/new String()/new Array()</code>. Satu form untuk semua penampung:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p: number      = new Contract()    // 1 elemen number, zeroed</span></span>
<span class="line"><span>buf: number    = new Contract(4)   // 4 elemen — sizeof(buf) == 16</span></span>
<span class="line"><span>list: number[] = new Contract(8)   // blok 8 elemen (raw block)</span></span>
<span class="line"><span>data: People   = new Contract()    // sizeof(People) zeroed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>buf[2] = 7</span></span>
<span class="line"><span>list[1] = 99</span></span>
<span class="line"><span>p = &quot;str&quot;           // TypeError — kontrak type permanen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Aturan</th><th>Catatan</th></tr></thead><tbody><tr><td>Wajib anotasi</td><td><code>p = new Contract()</code> polos → TypeError (kontraknya anotasi itu)</td></tr><tr><td><code>T[]</code> = raw block</td><td>akses <code>list[i]</code> via indexing — satu model dengan scalar</td></tr><tr><td>Struct member access</td><td><code>data.age = 30</code> / <code>print(data.age)</code> — offset dari layout struct, tipe field dicek</td></tr><tr><td>Registry v3</td><td>nama tipe elemen tersimpan di registry → view check = lookup</td></tr></tbody></table><p><strong>Member access struct</strong> — field scalar (<code>number/decimal/boolean</code>) baca- tulis native via layout offset; field tak dikenal ditolak:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: People = new Contract()</span></span>
<span class="line"><span>data.age = 30</span></span>
<span class="line"><span>data.score = 3.14</span></span>
<span class="line"><span>data.active = true</span></span>
<span class="line"><span>print(data.age)          // 30</span></span>
<span class="line"><span>data.ghost = 1          // TypeError: unknown field</span></span></code></pre></div><p>Field kompleks (<code>array/struct</code>) pada buffer scalar menghasilkan snapshot object read-only — buffer menyimpan byte mentah, bukan char*. Indexing elemen tetap tersedia: <code>data[0]</code>, dan handle nested (<code>p2: Point = new Contract()</code>; <code>p2.x + p2.y</code>) bekerja penuh.</p><p><strong>String slot first-class</strong> — field/variable <code>string</code> pada handle Contract benar-benar menyimpan teks: assignment menulis ke slot (write-through), pembacaan membaca slot (read-through):</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: string = new Contract()   // slot string, kosong</span></span>
<span class="line"><span>name = &quot;rudi&quot;                   // tulis ke slot (gcstrdup internal)</span></span>
<span class="line"><span>name = dupl(&quot;rudi&quot;, 3)          // tulis ptr hasil dupl ke slot</span></span>
<span class="line"><span>print(name)                     // read-through → &quot;rudi&quot;</span></span>
<span class="line"><span>type(name)                      // &quot;string&quot; — handle ter-transparansi penuh</span></span></code></pre></div><p>RHS <strong>string atau ptr hasil dupl</strong> → tulis ke slot; RHS <strong>ptr lain</strong> → rebind handle biasa. <code>compare(name, &quot;rudi&quot;)</code> membaca slot.</p><h2 id="new-del-—-alokasi-type-driven-gc-tracked" tabindex="-1">new/del — alokasi type-driven (GC-tracked) <a class="header-anchor" href="#new-del-—-alokasi-type-driven-gc-tracked" aria-label="Permalink to &quot;new/del — alokasi type-driven (GC-tracked)&quot;">​</a></h2><p>Lapisan alokasi utama: bahasa MEMANFAATKAN pengetahuan tipe — ukuran otomatis <code>sizeof(T)</code>, <code>n</code> = jumlah <strong>elemen</strong> (byte tidak pernah muncul di API), hasil zeroed. Global — tanpa import.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = new Number()        // 1 elemen (zeroed)</span></span>
<span class="line"><span>x[0] = 42               // scalar = buffer 1 elemen; index 0</span></span>
<span class="line"><span>print(x[0])             // 42</span></span>
<span class="line"><span></span></span>
<span class="line"><span>arr = new Number(4)     // 4 elemen</span></span>
<span class="line"><span>arr[2] = 7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>big = new Number(100 * 100)        // n bisa ekspresi apa pun</span></span>
<span class="line"><span>bigger = new Number(big, 200 * 100) // realloc — handle lama dangling</span></span>
<span class="line"><span></span></span>
<span class="line"><span>del(x)                  // free — statement-style, tanpa assignment</span></span>
<span class="line"><span>del(a, b)               // variadic</span></span>
<span class="line"><span>del([a, b])             // dari array</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Bentuk</th><th>Semantik</th><th>Padanan pin era</th></tr></thead><tbody><tr><td><code>new T()</code></td><td>1 elemen, zeroed</td><td>elpin(1, sizeof(T))</td></tr><tr><td><code>new T(n)</code></td><td>n elemen, zeroed</td><td>elpin(n, sizeof(T))</td></tr><tr><td><code>new T(src, n)</code></td><td>realloc ke n elemen</td><td>repin(src, n·sizeof(T))</td></tr><tr><td><code>del(x, ...)</code> / <code>del([x, y])</code></td><td>free variadic / dari array</td><td>gcfree</td></tr></tbody></table><p><strong>Kapitalisasi</strong>: <code>new Number()</code>, bukan <code>new number()</code> — <code>new number()</code> bentrok dengan penanda tipe <code>x: number</code>. Bentuk kapital berlaku untuk scalar (<code>Number/String/Boolean/Decimal/Ptr</code>); struct pakai nama aslinya (<code>new People()</code>).</p><p><strong>Akses isi</strong> — scalar = buffer 1 elemen; <code>x[0]</code> baca/tulis dengan bounds check dari registry (ukuran blok tersimpan per alokasi):</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p = new Number(3)</span></span>
<span class="line"><span>p[3] = 1          // RangeError: out of bounds</span></span>
<span class="line"><span>q = new Number(p, 8)</span></span>
<span class="line"><span>q[7] = p[0]       // realloc selalu pindah — handle p dangling setelahnya</span></span></code></pre></div><p><strong>Kontrak type permanen</strong> — <code>x = new Number()</code> mencatat declared type <code>number</code> di binding, sehingga <code>x = &quot;str&quot;</code> ditolak TypeError sepanjang umur variable.</p><p><strong>Guard</strong> — <code>del</code> pada pointer bukan milik GC / double-free → <code>MemoryError</code> + eksekusi berhenti. <code>sizeof(p)</code> pada handle mengembalikan ukuran blok terdaftar (12 untuk <code>new Number(3)</code>).</p><h2 id="pin-family-—-sistem-memori-gc-tracked" tabindex="-1">pin family — sistem memori (GC-tracked) <a class="header-anchor" href="#pin-family-—-sistem-memori-gc-tracked" aria-label="Permalink to &quot;pin family — sistem memori (GC-tracked)&quot;">​</a></h2><p>Keluarga alokasi memori yang terdaftar di registry GC. Global — tanpa import.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p: ptr = pin(sizeof(number))      // malloc + register (tak diinisialisasi)</span></span>
<span class="line"><span>a: number[] = elpin(4, sizeof(number))  // calloc + register (zeroed)</span></span>
<span class="line"><span>p = repin(p, 64)                  // realloc — registry mengikuti</span></span>
<span class="line"><span>p = repins(p, 8, sizeof(number))  // reallocarray — NULL jika overflow</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Fungsi</th><th>Padanan C</th><th>Catatan</th></tr></thead><tbody><tr><td><code>pin(size)</code></td><td>malloc</td><td>mengembalikan null jika gagal</td></tr><tr><td><code>elpin(count, size)</code></td><td>calloc</td><td>memori di-nol-kan</td></tr><tr><td><code>repin(ptr, size)</code></td><td>realloc</td><td>pointer lama tidak valid setelah call — selalu reassign</td></tr><tr><td><code>repins(ptr, count, size)</code></td><td>reallocarray</td><td>tolak jika <code>count * size</code> overflow</td></tr></tbody></table><p><strong>View type check</strong> — anotasi menentukan cara handle dibaca (per TYPE, bukan per byte):</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x: number = pin(sizeof(number))   // OK</span></span>
<span class="line"><span>y: number = pin(sizeof(string))   // TypeError: number vs string</span></span>
<span class="line"><span>z: number = pin(64)               // TypeError: generic ptr (tanpa sizeof)</span></span>
<span class="line"><span>w: ptr    = pin(64)               // OK — ptr = handle generik</span></span>
<span class="line"><span>q: number = repin(x, 32)          // OK — inherit provenance</span></span></code></pre></div><p>Pointer yang tidak dimiliki GC ditolak oleh repin/repins (<code>MemoryError</code>). Cek kegagalan alokasi dengan <code>p == null</code>.</p><h2 id="operasi-blok-alokasi-string-gc-tracked" tabindex="-1">Operasi blok &amp; alokasi string (GC-tracked) <a class="header-anchor" href="#operasi-blok-alokasi-string-gc-tracked" aria-label="Permalink to &quot;Operasi blok &amp; alokasi string (GC-tracked)&quot;">​</a></h2><p>Operasi blok bekerja pada memori yang sudah ada (posisi tulis wajib ptr milik GC; posisi baca menerima ptr GC <strong>atau</strong> string biasa). Alokasi string menghasilkan ptr baru yang terdaftar di GC.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p = elpin(8, sizeof(number))</span></span>
<span class="line"><span>setpin(p, 0, 32)                // memset — clear buffer</span></span>
<span class="line"><span>q = copypin(p, &quot;rupa&quot;, 5)       // memcpy — string sebagai sumber baca</span></span>
<span class="line"><span>q == p                          // true — return dest</span></span>
<span class="line"><span></span></span>
<span class="line"><span>movepin(a, b, 8)                // memmove — aman overlap</span></span>
<span class="line"><span>pincmp(a, b, 8)                 // memcmp — &lt; 0 / 0 / &gt; 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d = dupin(&quot;hello&quot;)              // strdup — ptr baru terdaftar GC</span></span>
<span class="line"><span>m = maxdupin(&quot;hello world&quot;, 5)  // strndup — maksimal 5 char, NUL-terminated</span></span>
<span class="line"><span></span></span>
<span class="line"><span>s = dupl(&quot;hello&quot;)               // dupin baru — nama pendek, satu nama dua arity</span></span>
<span class="line"><span>t = dupl(&quot;hello world&quot;, 5)      // strndup baru — maksimal 5 char</span></span>
<span class="line"><span>compare(s, &quot;hello&quot;)             // pincmp baru — 0 jika sama, dua arity</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Fungsi</th><th>Padanan C</th><th>Return</th></tr></thead><tbody><tr><td><code>copypin(dest, src, n)</code></td><td>memcpy</td><td><code>dest</code> (chainable)</td></tr><tr><td><code>movepin(dest, src, n)</code></td><td>memmove (aman overlap)</td><td><code>dest</code> (chainable)</td></tr><tr><td><code>setpin(ptr, value, n)</code></td><td>memset</td><td><code>ptr</code> (chainable)</td></tr><tr><td><code>pincmp(a, b, n)</code></td><td>memcmp</td><td>number (&lt; 0 / 0 / &gt; 0)</td></tr><tr><td><code>dupin(str)</code></td><td>strdup</td><td>ptr (GC-tracked)</td></tr><tr><td><code>maxdupin(str, n)</code></td><td>strndup</td><td>ptr — selalu NUL-terminated (n + 1 byte)</td></tr><tr><td><code>unpin(ptr)</code></td><td>free</td><td>statement-style: <code>unpin(p)</code>, tanpa assignment</td></tr><tr><td><code>dupl(str)</code> / <code>dupl(str, n)</code></td><td>strdup / strndup</td><td>ptr (GC-tracked)</td></tr><tr><td><code>compare(a, b)</code> / <code>compare(a, b, n)</code></td><td>memcmp</td><td>number (&lt; 0 / 0 / &gt; 0)</td></tr></tbody></table><p><code>dupl</code>/<code>compare</code> adalah nama baru untuk <code>dupin</code>/<code>maxdupin</code>/<code>pincmp</code> — satu nama, dispatch by arity. Nama lama masih berfungsi.</p><p><strong>Guard</strong> — menulis ke pointer yang bukan milik GC → <code>MemoryError</code> (dan menghentikan eksekusi). <code>pincmp</code> boleh membandingkan dua string biasa karena read-only.</p><p><code>unpin(p)</code> membebaskan blok lebih awal (setara <code>free</code>) — registry menghapus alamat sehingga double-free tertangkap sebagai <code>MemoryError</code>. Kebutuhan utama tetap <code>gcclean</code> di akhir program; <code>unpin</code> ada untuk berjaga-jaga saat blok besar perlu dirilis sebelum selesai dipakai. Handle lama menjadi dangling setelah <code>unpin</code> — jangan dipakai lagi.</p><p>Catatan: <code>sizeof</code> menerima nama tipe — dan sejak registry v2 juga <em>handle</em> (<code>sizeof(p)</code> → ukuran blok terdaftar). <code>setpin</code> versi lama di design pointer (<code>setpin(s, len, size)</code>) sudah digantikan bentuk memset <code>(dst, byte, n)</code> ini.</p><blockquote><p>pin/elpin/repin/repins kini <strong>deprecated by design</strong> — gunakan <code>new/del</code> (lapisan type-driven di atas). Block ops &amp; dup family tetap sebagai lapisan byte rendah di atas handle.</p></blockquote>`,57)])])}const m=e(p,[["render",i]]);export{b as __pageData,m as default};
